#!/bin/sh
# CANDIDATO 3 de la vuelta 42: integrar_peticion_critica_rutina_existente, pieza 10 de
# cap_13. NO es una de las cuatro partes de la serie: es lo que L237 manda hacer DESPUES
# de practicar las cuatro, y por eso su censo de serie va en no y su veredicto con la
